sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //this BR parses the payload from Queue table
	//sets error_code and response_body on MSS Event Outbound record based on values received in Queue table
	//if http_code=200 then state is changed to Processed else state is changed to Error
	//retry_count is incremented by 1 for Error codes:429,204,5**,0,401 and retry_count=10 for any other error codes
    try {
        if (current.source.indexOf(gs.getProperty("x_hsb11_hsbc_mss_o.eventOutbound_uri")) > -1 || current.source.indexOf(gs.getProperty("x_hsb11_hsbc_mss_o.eventOutbound_GCP_uri_payload")) > -1) {

			var event_outbound_rec = current.response_to.agent_correlator.toString();

            var response = "";
            var xmlDoc = new XMLDocument2();
            xmlDoc.parseXML(current.payload.toString());
            response = xmlDoc.getNodeText("//result/output");
            var http_code_node = xmlDoc.getNode("//parameters/parameter");
            var http_code = http_code_node.getAttribute('value');
            var gr_eo = new GlideRecord("x_hsb11_hsbc_mss_o_mss_event_outbound");
            gr_eo.get(event_outbound_rec);
            gr_eo.response_date = new GlideDateTime();
            gr_eo.response_body = response;
            gr_eo.error_code = http_code;

            if (http_code == '200') {
                gr_eo.state = "Processed";
			//added code 0 for MSSRBXCE-335
			//added code 401 for MSSRBXCE-578
            } else if (http_code == '429' || http_code == '204' || http_code.charAt(0) == "5" || http_code == "0" || http_code == "401") {
				gr_eo.state = "Error";
                gr_eo.error_body = response;
                gr_eo.retry_count++;
            } else {
                gr_eo.error_body = response;
                gr_eo.state = "Error";
                gr_eo.retry_count = 10;
            }
            gr_eo.update();
        }
    } catch (e) {
        gs.info(e.message);
    }
})(current, previous);
